import pytest

from shopcart.money import to_money


@pytest.mark.parametrize("value", ["NaN", "Infinity", "-Infinity"])
def test_non_finite_values_are_rejected(value):
    with pytest.raises(ValueError):
        to_money(value)

from shopcart import Discount


def test_code_is_stored_as_given():
    assert Discount.from_config({"code": "ten", "percent": 10}).code == "ten"

from shopcart.inventory import Stock


def test_stock_is_consulted():
    assert Stock().available("X") >= 0
